		InOff: x.off, OutOff: out.off,
		C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
		OC: uint32(c.OutC), KH: uint32(c.KH), KW: uint32(c.KW), Pad: uint32(c.Pad),
		WOff: b.wOff(name + ".weight"), BOff: b.bOff(name + ".bias"),
	})
	return out
}

