#version 450
// (C, H, W) -> (H*W, C): attention runs over pixels with the channel axis as
// the feature, which is the transpose diffusers writes as
// view(B, C, H*W).transpose(1, 2).
//
// One invocation per output element, so the scattered access is on the read
// side and the (H*W, C) rows the projections consume come out contiguous.

#include "vae_common.glsl"

layout(local_size_x = 256) in;

void main() {
    uint idx = gl_GlobalInvocationID.x;
    uint hw = pc.H * pc.W;
    if (idx >= hw * pc.C) {
        return;
    }
    uint c = idx % pc.C;
    uint p = idx / pc.C;
    act[pc.outOff + idx] = act[pc.inOff + c * hw + p];
}
#version 450
// (H*W, C) -> (C, H, W), adding the attention block's residual on the way
// back. Fused because the alternative is a second full pass over the tensor
// for an elementwise add, and IDEAS §3.2's point is that these passes are
// pure bandwidth and the only win is not doing them.

#include "vae_common.glsl"

